// Octopath-style painted plates. Embedded so play.html stays one file.
export const PLATE_SRC = {
  town: 'data:image/jpeg;base64,',
  overworld: 'data:image/jpeg;base64,',
  forest: 'data:image/jpeg;base64,',
  dungeon: 'data:image/jpeg;base64,',
  battle: 'data:image/jpeg;base64,',
};


const cache = {};
export function plateImage(key) {
  if (!PLATE_SRC[key]) return null;
  if (!cache[key]) {
    const im = new Image();
    im.src = PLATE_SRC[key];
    cache[key] = im;
  }
  return cache[key];
}

export function plateKeyForMap(map) {
  if (!map) return 'overworld';
  const id = String(map.id || '');
  if (/inn|cottage|home|temple|store|smithy|guild|castle|throne|barracks|treasury|pedlar|workshop|watch/.test(id)) return 'town';
  if (map.town) return 'town';
  if (/hollow|ruin|anvil|cave|abyss|choir|drowned|laby|mine|deep/.test(id)) return 'dungeon';
  if (/forest|mill|vale|glass|wood|farview/.test(id)) return 'forest';
  return 'overworld';
}

export function drawPlate(ctx, key, w, h) {
  const im = plateImage(key);
  if (!im || !im.complete || !im.naturalWidth) return false;
  const iw = im.naturalWidth, ih = im.naturalHeight;
  const scale = Math.max(w / iw, h / ih);
  const dw = iw * scale, dh = ih * scale;
  const prev = ctx.imageSmoothingEnabled;
  ctx.imageSmoothingEnabled = true;
  ctx.drawImage(im, (w - dw) / 2, (h - dh) / 2, dw, dh);
  ctx.imageSmoothingEnabled = prev;
  return true;
}
